public class Main {
    public static void main(String[] args) throws Exception {
        java.util.Optional.of(new String(System.in.readAllBytes()).trim().split("\\s+")).map(in -> Arrays.stream(in).mapToLong(Long::parseLong).toArray()).map(d -> (Integer) (int) d[0] instanceof Integer cnt && (Long) (d[1] - 2000) instanceof Long year && new int[cnt] instanceof int[] before && IntStream.range(0, (int) d[2]).allMatch(e -> (before[(int) d[4 + 2 * e] - 1] |= 1 << ((int) d[3 + 2 * e] - 1)) >= 0) && IntStream.range(0, cnt + 1).map(e -> -1).toArray() instanceof int[] seatOf && new int[cnt] instanceof int[] ans && new int[][] {IntStream.range(0, 1 << cnt).toArray()} instanceof int[][] live && ((Supplier<long[]>) () -> new long[1 << cnt] instanceof long[] ways && (ways[0] = 1) > 0 && new IntBinaryOperator[1] instanceof IntBinaryOperator[] step && (step[0] = (sub, b) -> b >= cnt ? 0 : ((sub >> b & 1) == 0 && (before[b] & ~sub) == 0 && (seatOf[Integer.bitCount(sub)] >= 0 ? seatOf[Integer.bitCount(sub)] == b : ans[b] == 0) && (ways[sub | 1 << b] += ways[sub]) > 0 ? 1 : 0) + (seatOf[Integer.bitCount(sub)] >= 0 ? 0 : step[0].applyAsInt(sub, b + 1))) != null && Arrays.stream(live[0]).filter(sub -> ways[sub] != 0 && step[0].applyAsInt(sub, Math.max(0, seatOf[Integer.bitCount(sub)])) >= 0).toArray() instanceof int[] kept && (live[0] = kept) != null ? ways : null) instanceof Supplier<long[]> fwd && new long[] {year} instanceof long[] rest ? IntStream.range(0, cnt).allMatch(pos -> fwd.get() instanceof long[] ways && new long[1 << cnt] instanceof long[] back && (back[(1 << cnt) - 1] = 1) > 0 && new long[cnt] instanceof long[] tally && new IntBinaryOperator[1] instanceof IntBinaryOperator[] step && (step[0] = (sub, b) -> b >= cnt ? 0 : ((sub >> b & 1) == 0 && (before[b] & ~sub) == 0 && (seatOf[Integer.bitCount(sub)] >= 0 ? seatOf[Integer.bitCount(sub)] == b : ans[b] == 0) && (back[sub] += back[sub | 1 << b]) > 0 ? 1 : 0) + (seatOf[Integer.bitCount(sub)] >= 0 ? 0 : step[0].applyAsInt(sub, b + 1))) != null && IntStream.range(0, live[0].length).map(h -> live[0][live[0].length - 1 - h]).filter(sub -> ((sub >> pos & 1) != 0 || (before[pos] & ~sub) != 0 || seatOf[Integer.bitCount(sub)] >= 0 || (tally[Integer.bitCount(sub)] += ways[sub] * back[sub | 1 << pos]) >= 0) && step[0].applyAsInt(sub, Math.max(0, seatOf[Integer.bitCount(sub)])) >= 0).count() >= 0 && IntStream.range(0, cnt).anyMatch(rk -> tally[rk] >= rest[0] ? (seatOf[rk] = pos) >= 0 && (ans[pos] = rk + 1) > 0 : (rest[0] -= tally[rk]) < 0)) ? String.join(" ", Arrays.stream(ans).mapToObj(String::valueOf).toList()) : "The times have changed" : "").ifPresent(System.out::println);
    }
}

